mapper.select:
select r.review_id, r.call_id, r.agent_code, r.prompt_version, r.biz_type, r.biz_id, r.status, r.flags,
       r.reviewer, r.review_time, r.reason, r.create_by, r.create_time, r.update_by, r.update_time, r.remark
from abr_ai_review r


        AND r.agent_code = #{agentCode}


        AND r.status = #{status}


        AND r.biz_type = #{bizType}


        AND r.biz_id = #{bizId}


        AND r.call_id = #{callId}


        AND r.create_time >= cast(#{params.beginTime} as date)


        AND r.create_time < cast(#{params.endTime} as date) + interval '1 day'


order by r.review_id desc
